// Valida X-Webhook-Secret contra la env var.
const headers = $input.first().json.headers ?? {};
const received =
  headers['x-webhook-secret'] ?? headers['X-Webhook-Secret'];
const expected = $env.WEBHOOK_SECRET;

if (!expected) {
  throw new Error('WEBHOOK_SECRET not set. Restart n8n with ~/start-n8n.sh.');
}
if (!received) {
  throw new Error('Missing X-Webhook-Secret header.');
}
if (received !== expected) {
  throw new Error('Invalid X-Webhook-Secret.');
}

return $input.all();

// Llama a Gemini 2.5 Flash con prompt que pide los datos del menú.
// Devuelve el JSON extraído tal cual lo dió el LLM.

const pdfText = ($input.first().json.text ?? '').trim();
if (!pdfText) {
  throw new Error('No text extracted from PDF (probablemente PDF escaneado; Vision LLM no implementado todavía).');
}

const apiKey = $env.GEMINI_API_KEY;
if (!apiKey) throw new Error('GEMINI_API_KEY not set');

const prompt =
  'Sos un asistente experto en menús de restaurantes argentinos. Te paso el texto de un menú PDF y tenés que devolver SOLO un JSON con la estructura exacta de abajo. Sin markdown, sin explicaciones, sin texto extra.\n\n' +
  'ESTRUCTURA:\n' +
  '{\n' +
  '  "info": {\n' +
  '    "name": <nombre REAL del restaurante tal como aparece en el header del menú; NO uses placeholders como "Restaurante Argentino">,\n' +
  '    "location": <ubicación REAL del restaurante si aparece en el PDF, ej "Pueyrredón, Córdoba"; si no aparece usá la string literal "_dato no disponible_">,\n' +
  '    "subtitle": <subtítulo o slogan si aparece; o omití el campo>,\n' +
  '    "description": <descripción corta si aparece; o omití>,\n' +
  '    "theme": {\n' +
  '      "primaryColor": <hex de color de la marca según colores del PDF, ej "#C62828">,\n' +
  '      "backgroundColor": <hex de fondo, ej "#FAFAFA">,\n' +
  '      "textColor": <hex texto, ej "#1A1A1A">,\n' +
  '      "accentColor": <hex acento, variante del primary>,\n' +
  '      "fonts": {\n' +
  '        "heading": <CSS font-family para títulos, ej "Georgia, serif">,\n' +
  '        "body": <CSS font-family para body, ej "\'Helvetica Neue\', sans-serif">\n' +
  '      }\n' +
  '    }\n' +
  '  },\n' +
  '  "menuSections": [\n' +
  '    { "id": <kebab-case ASCII>, "title": <título humano>, "items": ["<item-slug>", ...] }\n' +
  '  ],\n' +
  '  "items": {\n' +
  '    "<item-slug>": {\n' +
  '      "slug": <mismo que la key>,\n' +
  '      "name": <nombre del plato>,\n' +
  '      "price": <SOLO dígitos como string, ej "5500"; si no encontrás precio usá la string literal "_dato no disponible_">,\n' +
  '      "shortDescription": <descripción corta opcional>,\n' +
  '      "description": <descripción larga opcional>,\n' +
  '      "ingredients": [<si los hay>],\n' +
  '      "type": <categoría libre, ej "Pizza napolitana">,\n' +
  '      "icon": <emoji según categoría: pizza:🍕 pasta:🍝 ensalada:🥗 carne:🥩 hamburguesa:🍔 pescado:🐟 postre:🍰 vino:🍷 cerveza:🍺 café:☕ bebida:🥤 sushi:🍣 sopa:🍲 tapa:🍢 vermut:🍹 picada:🧀 sandwich:🥪 fritura:🍟 pan/focaccia:🥖 empanada:🥟 default:🍽️>\n' +
  '    }\n' +
  '  }\n' +
  '}\n\n' +
  'REGLAS DURAS:\n' +
  '- Slugs SIEMPRE kebab-case ASCII sin acentos ("papas-bravas", no "papás-bravas").\n' +
  '- Cada slug en menuSections.items DEBE existir en items{}.\n' +
  '- price SIEMPRE string, solo dígitos sin "$" ni puntos ("5500", no "$5.500").\n' +
  '- Idioma español argentino.\n' +
  '- Si el texto NO es un menú: respondé exactamente {"error":"no_es_menu"}.\n\n' +
  'TEXTO DEL MENÚ:\n\n' +
  pdfText;

const payload = {
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: { responseMimeType: 'application/json', temperature: 0.2 },
};

const url =
  'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=' +
  apiKey;

let data;
try {
  data = await this.helpers.httpRequest({
    method: 'POST',
    url: url,
    body: payload,
    json: true,
    headers: { 'Content-Type': 'application/json' },
    returnFullResponse: false,
  });
} catch (err) {
  const status = err?.httpCode ?? err?.statusCode ?? '?';
  const body = err?.response?.body ?? err?.message ?? 'unknown';
  throw new Error('Gemini API error ' + status + ': ' + JSON.stringify(body).slice(0, 400));
}

const raw = data?.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (err) {
  return [{ json: { ok: false, error: 'gemini_returned_invalid_json', rawSample: raw.slice(0, 500) } }];
}

if (parsed?.error === 'no_es_menu') {
  return [{ json: { ok: false, error: 'no_es_menu', message: parsed.message ?? '' } }];
}

return [{
  json: {
    ok: true,
    extracted: parsed,
    pdfCharCount: pdfText.length,
    promptCharCount: prompt.length,
  },
}];

// Toma el extracted de Gemini, lo envuelve en el formato completo del
// schema (status, version, dates, _meta, theme defaults, etc), genera
// un slug único contra el repo, y commitea via GitHub Contents API.

const input = $input.first().json;
if (!input?.ok || !input?.extracted) {
  // Pass-through del error del nodo anterior.
  return [{ json: input }];
}
const ext = input.extracted;

const owner = $env.GITHUB_OWNER;
const repo = $env.GITHUB_REPO;
const branch = $env.GITHUB_BRANCH || 'main';
const token = $env.GITHUB_TOKEN;
if (!owner || !repo || !token) {
  throw new Error('Missing GITHUB_OWNER / GITHUB_REPO / GITHUB_TOKEN env vars.');
}

// Slug helper: kebab-case ASCII, sin acentos.
function makeSlug(name) {
  return String(name || 'restaurant')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s-]/g, '')
    .trim()
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');
}

let baseSlug = makeSlug(ext?.info?.name);
if (baseSlug.length < 3) baseSlug = 'restaurant';

// Resolver slug único contra el repo. ignoreHttpStatusErrors=true para que
// el helper devuelva la response en lugar de throw en 404.
const self = this;
async function existsInRepo(slug) {
  const resp = await self.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/content/restaurants/${slug}.json?ref=${branch}`,
    headers: { Authorization: `Bearer ${token}`, Accept: 'application/vnd.github+json' },
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
  if (resp.statusCode === 200) return true;
  if (resp.statusCode === 404) return false;
  throw new Error('Unexpected status checking slug uniqueness: ' + resp.statusCode);
}

let slug = baseSlug;
let n = 2;
while (await existsInRepo(slug)) {
  slug = `${baseSlug}-${n++}`;
  if (n > 50) throw new Error('Too many slug collisions (>50)');
}

// Construir el JSON completo según el schema.
const now = new Date().toISOString();
const defaultTheme = {
  primaryColor: '#2C2C2C',
  backgroundColor: '#FAFAFA',
  textColor: '#1A1A1A',
  accentColor: '#777777',
  fonts: {
    heading: 'Georgia, serif',
    body: "'Helvetica Neue', Helvetica, Arial, sans-serif",
  },
};

const restaurant = {
  $schema: '../../schema/menu.schema.json',
  slug,
  status: 'active',
  version: 1,
  createdAt: now,
  updatedAt: now,
  _meta: {
    sourcePdfName: 'webhook-upload.pdf',
    extractedBy: 'gemini-2.5-flash',
    missingFields: [],
  },
  info: {
    name: ext?.info?.name || '_dato no disponible_',
    ...(ext?.info?.location ? { location: ext.info.location } : {}),
    ...(ext?.info?.subtitle ? { subtitle: ext.info.subtitle } : {}),
    ...(ext?.info?.description ? { description: ext.info.description } : {}),
    theme: ext?.info?.theme ?? defaultTheme,
  },
  menuSections: Array.isArray(ext?.menuSections) ? ext.menuSections : [],
  items: (ext?.items && typeof ext.items === 'object') ? ext.items : {},
};

// Sanity defaults en cada item.
for (const [key, item] of Object.entries(restaurant.items)) {
  if (item && typeof item === 'object') {
    item.slug = item.slug || key;
    item.name = item.name || key;
    item.icon = item.icon || '🍽️';
    if (item.price === undefined || item.price === null || item.price === '') {
      item.price = '_dato no disponible_';
    } else {
      item.price = String(item.price);
    }
  }
}

// Validación mínima.
if (!restaurant.info.name || restaurant.menuSections.length === 0 || Object.keys(restaurant.items).length === 0) {
  throw new Error('Restaurant JSON invalid: empty name / no sections / no items.');
}

const content = JSON.stringify(restaurant, null, 2) + '\n';
const contentB64 = Buffer.from(content, 'utf8').toString('base64');

// Commit via GitHub Contents API.
let commitResp;
try {
  commitResp = await this.helpers.httpRequest({
    method: 'PUT',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/content/restaurants/${slug}.json`,
    headers: { Authorization: `Bearer ${token}`, Accept: 'application/vnd.github+json' },
    body: { message: `feat(content): add ${slug}`, content: contentB64, branch },
    json: true,
  });
} catch (err) {
  throw new Error('GitHub commit failed: ' + (err?.message ?? String(err)).slice(0, 500));
}

return [{
  json: {
    ok: true,
    slug,
    publicUrl: `https://menudigital-platform.vercel.app/r/${slug}/`,
    commitSha: commitResp?.commit?.sha,
    commitUrl: commitResp?.commit?.html_url,
    itemsCount: Object.keys(restaurant.items).length,
    sectionsCount: restaurant.menuSections.length,
  },
}];
